const rows = await query(`PRAGMA index_info('idx_tasks_user_status');`);

if (rows.length !== 2) {
  throw new Error(`Expected 2 indexed columns, got ${rows.length}`);
}

const columns = rows
  .sort((a, b) => a.seq - b.seq)
  .map(row => row.name);

if (columns[0] !== 'user_id' || columns[1] !== 'status') {
  throw new Error(`Expected index columns user_id, status; got ${columns.join(', ')}`);
}

return true;

